#!/usr/bin/env bash
# Compiles DeadboltAutoFill.appex (anomaly.deadbolt.autofill) from
# crates/app/autofill/*.swift and deadbolt-ffi (libdeadbolt_ffi.a, with its
# Swift bindings generated by crates/ffi/bindgen), stamps Info.plist, and
# signs ad hoc (or with DEADBOLT_APPLE_SIGNING_IDENTITY +
# DEADBOLT_AUTOFILL_PROVISION_PROFILE).
#
#   crates/app/scripts/build-autofill.sh [--universal] [--tests]
#     [--ffi-target-dir <dir>] <out.appex> [version] [build]
#
# --ffi-target-dir: a Cargo target directory where deadbolt-ffi's release
#   library is already built (`release/`, or `<arch>-apple-darwin/release/`
#   for --universal), as bundle.sh does with the rest; otherwise this builds it.
# --tests: the AutoFillTests.swift runner in the extension's place
#   (crates/app/tests/app/autofill.rs), with its own main.
set -euo pipefail

[[ $(uname -s) == Darwin ]] || { echo "Building DeadboltAutoFill.appex requires macOS." >&2; exit 1; }

universal=false
tests=false
ffi_target=
while [[ ${1:-} == --* ]]; do
  case $1 in
    --universal) universal=true; shift ;;
    --tests) tests=true; shift ;;
    --ffi-target-dir) ffi_target=${2:?--ffi-target-dir needs a directory}; shift 2 ;;
    *) echo "Unknown option: $1" >&2; exit 1 ;;
  esac
done

[[ $# -ge 1 && $# -le 3 ]] || {
  echo "Usage: $0 [--universal] [--tests] [--ffi-target-dir <dir>] <out.appex> [version] [build]" >&2
  exit 1
}

root=$(cd "$(dirname "$0")/../../.." && pwd)
out=$1
[[ $out == /* ]] || out="$PWD/$out"
[[ ! -e "$out" && ! -L "$out" ]] || { echo "Refusing to replace $out; choose a fresh output path." >&2; exit 1; }

version=${2:-}
build=${3:-}
if [[ -z $version ]]; then
  version=$(cargo +stable metadata --manifest-path "$root/Cargo.toml" --no-deps --format-version 1 | python3 -c 'import json,sys; print(next(p["version"] for p in json.load(sys.stdin)["packages"] if p["name"] == "deadbolt-app"))')
fi
if [[ -z $build ]]; then
  case "$version" in
    0.0.0-dev-*) build=${version#0.0.0-dev-}; build=${build%%.*} ;;
    *) build=$(printf '%s\n' "${version%%-*}" | awk -F. '{ print ($1 * 10000) + ($2 * 100) + $3 }') ;;
  esac
fi

scratch=$(mktemp -d)
trap 'rm -rf "$scratch"' EXIT

if $universal; then
  arches=(aarch64 x86_64)
else
  case "$(uname -m)" in
    arm64) arches=(aarch64) ;;
    x86_64) arches=(x86_64) ;;
    *) echo "Unsupported macOS architecture: $(uname -m)" >&2; exit 1 ;;
  esac
fi

# libdeadbolt_ffi.a for <arch>: per target for a universal build, the host's
# own otherwise (as `cargo build` without --target leaves it).
ffi_lib() {
  if $universal; then echo "$ffi_target/$1-apple-darwin/release/libdeadbolt_ffi.a"; else echo "$ffi_target/release/libdeadbolt_ffi.a"; fi
}
target=$(cargo +stable metadata --manifest-path "$root/Cargo.toml" --no-deps --format-version 1 | python3 -c 'import json,sys; print(json.load(sys.stdin)["target_directory"])')
if [[ -z $ffi_target ]]; then
  # Its C (blake3's, say) for the extension's own minimum macOS.
  export MACOSX_DEPLOYMENT_TARGET=${MACOSX_DEPLOYMENT_TARGET:-14.0}
  ffi_target=$target
  if $universal; then
    cargo +stable build --manifest-path "$root/Cargo.toml" --release --locked -p deadbolt-ffi --lib \
      --target aarch64-apple-darwin --target x86_64-apple-darwin >&2
  else
    cargo +stable build --manifest-path "$root/Cargo.toml" --release --locked -p deadbolt-ffi --lib >&2
  fi
fi
for arch in "${arches[@]}"; do
  [[ -f $(ffi_lib "$arch") ]] || { echo "Missing $(ffi_lib "$arch"); build deadbolt-ffi first." >&2; exit 1; }
done

# The Swift bindings, from the library's own UniFFI metadata. The generator
# builds in its own target directory: its own workspace, and never waiting on
# a build that runs this script.
CARGO_TARGET_DIR="$target/uniffi-bindgen" cargo +stable build --manifest-path "$root/crates/ffi/bindgen/Cargo.toml" --locked -q >&2
(cd "$root" && "$target/uniffi-bindgen/debug/uniffi-bindgen" generate --no-format \
  --library "$(ffi_lib "${arches[0]}")" --language swift --out-dir "$scratch/ffi" >&2)
[[ -f $scratch/ffi/deadbolt_ffi.swift && -f $scratch/ffi/deadbolt_ffiFFI.modulemap ]] ||
  { echo "uniffi-bindgen wrote no Swift bindings for deadbolt-ffi." >&2; exit 1; }

src_dir="$root/crates/app/autofill"
sources=(
  "$scratch/ffi/deadbolt_ffi.swift"
  "$src_dir/Models.swift"
  "$src_dir/Client.swift"
  "$src_dir/IdentitySync.swift"
  "$src_dir/ControllerModel.swift"
  "$src_dir/AutoFillView.swift"
  "$src_dir/CredentialProviderViewController.swift"
)
if $tests; then
  sources+=("$src_dir/tests/AutoFillTests.swift")
  entry=()
else
  # An app extension starts in NSExtensionMain, and uses only the APIs app
  # extensions may.
  entry=(-application-extension -Xlinker -e -Xlinker _NSExtensionMain)
fi

compile_slice() {
  local arch=$1
  local dest=$2
  local triple=$arch-apple-macosx14.0
  [[ $arch == aarch64 ]] && triple=arm64-apple-macosx14.0
  swiftc -O -swift-version 6 -warnings-as-errors \
    -module-name DeadboltAutoFill \
    -parse-as-library \
    ${entry[@]+"${entry[@]}"} \
    -target "$triple" \
    -Xcc -fmodule-map-file="$scratch/ffi/deadbolt_ffiFFI.modulemap" \
    -I "$scratch/ffi" \
    "${sources[@]}" \
    "$(ffi_lib "$arch")" \
    -framework AppKit \
    -framework AuthenticationServices \
    -framework CoreFoundation \
    -framework Security \
    -Xlinker -dead_strip \
    -o "$dest"
}

appex="$scratch/DeadboltAutoFill.appex"
mkdir -p "$appex/Contents/MacOS"

slices=()
for arch in "${arches[@]}"; do
  compile_slice "$arch" "$scratch/DeadboltAutoFill-$arch"
  slices+=("$scratch/DeadboltAutoFill-$arch")
done
lipo -create "${slices[@]}" -output "$appex/Contents/MacOS/DeadboltAutoFill"
chmod 755 "$appex/Contents/MacOS/DeadboltAutoFill"

sed \
  -e "s|@VERSION@|$version|g" \
  -e "s|@BUILD@|$build|g" \
  "$src_dir/Info.plist.in" > "$appex/Contents/Info.plist"
plutil -lint "$appex/Contents/Info.plist" >/dev/null

if [[ -n ${DEADBOLT_AUTOFILL_PROVISION_PROFILE:-} ]]; then
  cp "$DEADBOLT_AUTOFILL_PROVISION_PROFILE" "$appex/Contents/embedded.provisionprofile"
fi

sign_id=${DEADBOLT_APPLE_SIGNING_IDENTITY:--}
if [[ $sign_id != "-" ]]; then
  team_id=${DEADBOLT_APPLE_TEAM_ID:-${DEADBOLT_TEAM_ID:-}}
  if [[ -z $team_id && $sign_id =~ \(([A-Za-z0-9]{10})\)$ ]]; then
    team_id=${BASH_REMATCH[1]}
  fi
  [[ -n $team_id ]] || {
    echo "DEADBOLT_APPLE_SIGNING_IDENTITY ($sign_id) names no team: set DEADBOLT_APPLE_TEAM_ID." >&2
    exit 1
  }
  cat > "$scratch/autofill.entitlements" <<ENTITLEMENTS
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>com.apple.security.app-sandbox</key>
    <true/>
    <key>com.apple.developer.authentication-services.autofill-credential-provider</key>
    <true/>
    <key>com.apple.security.application-groups</key>
    <array>
        <string>${team_id}.anomaly.deadbolt</string>
    </array>
</dict>
</plist>
ENTITLEMENTS
  plutil -lint "$scratch/autofill.entitlements" >/dev/null
  codesign --force --options runtime --timestamp \
    --identifier anomaly.deadbolt.autofill \
    --entitlements "$scratch/autofill.entitlements" \
    --sign "$sign_id" \
    "$appex"
else
  codesign --force --identifier anomaly.deadbolt.autofill --sign - "$appex"
fi

codesign --verify --strict "$appex"

mkdir -p "$(dirname "$out")"
mv "$appex" "$out"
echo "$out"
